/// A group type with the roles it has, by position.
#[derive(Clone)]
struct TypeWithRoles {
    group_type: group_types::Model,
    roles: Vec<group_type_roles::Model>,
}

impl TypeWithRoles {
    fn to_schema(&self) -> GroupType {
        let t = &self.group_type;
        GroupType {
            id: t.id,
            label: t.label.clone(),
            label_translation_key: t.label_translation_key.clone(),
            position: i64::from(t.position),
            roles: self.roles.iter().map(role).collect(),
        }
    }
}

fn role(r: &group_type_roles::Model) -> GroupTypeRole {
    GroupTypeRole {
        id: r.id,
        group_type_id: r.group_type_id,
        label: r.label.clone(),
        label_translation_key: r.label_translation_key.clone(),
        position: r.position.map(i64::from),
    }
}

/// The group types `ids` with their roles (`orderBy('position')`).
async fn load_types<C: ConnectionTrait>(db: &C, ids: Vec<Id>) -> ApiResult<HashMap<Id, TypeWithRoles>> {
    let mut out = HashMap::new();
    if ids.is_empty() {
        return Ok(out);
    }
    for t in group_types::Entity::find().filter(group_types::Column::Id.is_in(ids.clone())).all(db).await? {
        out.insert(t.id, TypeWithRoles { group_type: t, roles: Vec::new() });
    }
    let mut roles = group_type_roles::Entity::find()
        .filter(group_type_roles::Column::GroupTypeId.is_in(ids))
        .order_by_asc(group_type_roles::Column::Id)
        .all(db)
        .await?;
    // `orderBy('position')`, with NULL positions first as MySQL and SQLite
    // sort them.
    roles.sort_by_key(|r| r.position);
    for r in roles {
        if let Some(t) = out.get_mut(&r.group_type_id) {
            t.roles.push(r);
        }
    }
    Ok(out)
}

/// The members of each group: its contacts (soft-deleted ones excluded)
/// with their age and role, by first name.
async fn load_members<C: ConnectionTrait>(db: &C, group_ids: Vec<Id>) -> ApiResult<HashMap<Id, Vec<GroupMember>>> {
    let mut out: HashMap<Id, Vec<GroupMember>> = HashMap::new();
    if group_ids.is_empty() {
        return Ok(out);
    }
    let links = contact_group::Entity::find().filter(contact_group::Column::GroupId.is_in(group_ids)).all(db).await?;
    if links.is_empty() {
        return Ok(out);
    }
    let contact_ids: Vec<Uuid> = links.iter().map(|l| l.contact_id).collect();
    let contacts: HashMap<Uuid, contacts::Model> = contacts::Entity::live()
        .filter(contacts::Column::Id.is_in(contact_ids))
        .all(db)
        .await?
        .into_iter()
        .map(|c| (c.id, c))
        .collect();
    let list: Vec<contacts::Model> = contacts.values().cloned().collect();
    let ages = super::views::ages(db, &list).await?;
    for link in links {
        let Some(c) = contacts.get(&link.contact_id) else { continue };
        out.entry(link.group_id).or_default().push(GroupMember {
            id: c.id,
            vault_id: c.vault_id,
            first_name: c.first_name.clone(),
            middle_name: c.middle_name.clone(),
            last_name: c.last_name.clone(),
            nickname: c.nickname.clone(),
            maiden_name: c.maiden_name.clone(),
            prefix: c.prefix.clone(),
            suffix: c.suffix.clone(),
            avatar_file_id: c.file_id.map(|f| f.0),
            listed: c.listed,
            age: ages.get(&c.id).copied().flatten(),
            group_type_role_id: link.group_type_role_id.map(|r| r.0),
        });
    }
    for members in out.values_mut() {
        crate::text::sort_by_collator(members, |m| m.first_name.clone().unwrap_or_default());
    }
    Ok(out)
}

/// The read models of `rows`, in their order, with their types and members.
async fn load_groups<C: ConnectionTrait>(
    db: &C,
    rows: Vec<groups::Model>,
) -> ApiResult<Vec<(Group, Option<TypeWithRoles>)>> {
    let types = load_types(db, rows.iter().filter_map(|g| g.group_type_id).collect()).await?;
    let mut members = load_members(db, rows.iter().map(|g| g.id).collect()).await?;
    Ok(rows
        .into_iter()
        .map(|g| {
            let group_type = g.group_type_id.and_then(|id| types.get(&id)).cloned();
            let group = Group {
                id: g.id,
                vault_id: g.vault_id,
                name: g.name,
                group_type: group_type.as_ref().map(TypeWithRoles::to_schema),
                members: members.remove(&g.id).unwrap_or_default(),
                created_at: g.created_at.unwrap_or_else(crate::db::now),
                updated_at: g.updated_at.unwrap_or_else(crate::db::now),
            };
            (group, group_type)
        })
        .collect())
}

async fn load_group<C: ConnectionTrait>(db: &C, row: groups::Model) -> ApiResult<(Group, Option<TypeWithRoles>)> {
    Ok(load_groups(db, vec![row]).await?.pop().expect("one group"))
}

/// `$vault->groups()->findOrFail($id)`: a group of the vault, not deleted.
async fn find_group(state: &AppState, vault_id: Uuid, group_id: Id) -> ApiResult<groups::Model> {
    groups::Entity::live()
        .filter(groups::Column::Id.eq(group_id))
        .filter(groups::Column::VaultId.eq(vault_id))
        .one(&state.db)
        .await?
        .ok_or_else(ApiError::not_found)
}

/// `group_type_id` is one of the account's group types (422 `exists`
/// otherwise; the service answers 404 for another account's).
async fn check_group_type(state: &AppState, v: &mut Validator, account_id: Uuid, id: Option<Id>) -> ApiResult<()> {
    if let Some(id) = id
        && group_types::Entity::find_by_id(id)
            .filter(group_types::Column::AccountId.eq(account_id))
            .one(&state.db)
            .await?
            .is_none()
    {
        v.fail("group_type_id", "exists", &[]);
    }
    Ok(())
}

fn check_name(v: &mut Validator, name: &Option<String>) {
    if v.required("name", name) {
        v.max_len("name", name.as_deref(), 255);
    }
}

