#[utoipa::path(
    get,
    path = "/vaults/{vault_id}/groups/{group_id}",
    operation_id = "getVaultGroup",
    tag = "Groups",
    summary = "Get a group with its members bucketed by role",
    params(("vault_id" = uuid::Uuid, Path), ("group_id" = i64, Path)),
    responses((status = 200, description = "The group.", body = GroupDetail), (status = 401, description = "No valid session or token (`unauthenticated`)."), (status = 403, description = "`forbidden`, `csrf_token_mismatch`, `email_not_verified`, `token_ability_missing`, `password_confirmation_required` or `signup_disabled`."), (status = 404, description = "Doesn't exist or isn't visible to the user (`not_found`).")),
    extensions(("x-permission" = json!("vault:view")), ("x-inventory" = json!(["R127", "R128"])), ("x-services" = json!([])))
)]
pub async fn get_vault_group(
    State(state): State<AppState>,
    Auth(id): Auth,
    Path((vault_id, group_id)): Path<(Uuid, Id)>,
) -> ApiResult<Json<GroupDetail>> {
    access::vault(&state, &id, vault_id, VaultPermission::View).await?;
    let row = find_group(&state, vault_id, group_id).await?;
    let (group, group_type) = load_group(&state.db, row).await?;

    // `GroupShowViewHelper::data`: a bucket per role of the type, then the
    // members without one of those roles.
    let type_roles = group_type.map(|t| t.roles).unwrap_or_default();
    let mut roles: Vec<GroupDetailRole> = type_roles
        .iter()
        .map(|r| GroupDetailRole {
            role: Some(role(r)),
            members: group.members.iter().filter(|m| m.group_type_role_id == Some(r.id.0)).cloned().collect(),
        })
        .collect();
    let without_role: Vec<GroupMember> = group
        .members
        .iter()
        .filter(|m| !type_roles.iter().any(|r| m.group_type_role_id == Some(r.id.0)))
        .cloned()
        .collect();
    if !without_role.is_empty() {
        roles.push(GroupDetailRole { role: None, members: without_role });
    }

    Ok(Json(GroupDetail {
        id: group.id,
        vault_id: group.vault_id,
        name: group.name,
        group_type: group.group_type,
        members: group.members,
        created_at: group.created_at,
        updated_at: group.updated_at,
        roles,
    }))
}

#[utoipa::path(
    patch,
    path = "/vaults/{vault_id}/groups/{group_id}",
    operation_id = "updateVaultGroup",
    tag = "Groups",
    summary = "Rename a group or change its type",
    params(("vault_id" = uuid::Uuid, Path), ("group_id" = i64, Path)),
    request_body = GroupUpdate,
    responses((status = 200, description = "The updated group.", body = Group), (status = 401, description = "No valid session or token (`unauthenticated`)."), (status = 403, description = "`forbidden`, `csrf_token_mismatch`, `email_not_verified`, `token_ability_missing`, `password_confirmation_required` or `signup_disabled`."), (status = 404, description = "Doesn't exist or isn't visible to the user (`not_found`)."), (status = 422, description = "`validation_failed` (with `errors`), `storage_limit_exceeded` or `vault_user_limit_reached`.")),
    extensions(("x-permission" = json!("vault:edit")), ("x-inventory" = json!(["R129"])), ("x-services" = json!(["UpdateGroup"])))
)]
pub async fn update_vault_group(
    State(state): State<AppState>,
    Auth(id): Auth,
    Path((vault_id, group_id)): Path<(Uuid, Id)>,
    Json(body): Json<GroupUpdate>,
) -> ApiResult<Json<Group>> {
    access::vault(&state, &id, vault_id, VaultPermission::Edit).await?;
    let group = find_group(&state, vault_id, group_id).await?;
    let mut v = Validator::new();
    let name = match body.name {
        Some(n) => {
            let n = clean(Some(n));
            check_name(&mut v, &n);
            n
        }
        None => Some(group.name.clone()),
    };
    let group_type_id = match body.group_type_id {
        Some(t) => {
            let t = t.map(Id);
            check_group_type(&state, &mut v, id.user.account_id, t).await?;
            t
        }
        None => group.group_type_id,
    };
    v.finish()?;
    let tx = state.db.begin().await?;
    let group = UpdateGroup {
        account_id: id.user.account_id,
        vault_id,
        author_id: id.user.id,
        group_id: group.id,
        group_type_id,
        name,
    }
    .execute(&tx)
    .await?;
    tx.commit().await?;
    Ok(Json(load_group(&state.db, group).await?.0))
}

#[utoipa::path(
    delete,
    path = "/vaults/{vault_id}/groups/{group_id}",
    operation_id = "deleteVaultGroup",
    tag = "Groups",
    summary = "Delete a group",
    params(("vault_id" = uuid::Uuid, Path), ("group_id" = i64, Path)),
    responses((status = 204, description = "Done; no body."), (status = 401, description = "No valid session or token (`unauthenticated`)."), (status = 403, description = "`forbidden`, `csrf_token_mismatch`, `email_not_verified`, `token_ability_missing`, `password_confirmation_required` or `signup_disabled`."), (status = 404, description = "Doesn't exist or isn't visible to the user (`not_found`).")),
    extensions(("x-permission" = json!("vault:edit")), ("x-inventory" = json!(["R130"])), ("x-services" = json!(["DestroyGroup"])))
)]
pub async fn delete_vault_group(
    State(state): State<AppState>,
    Auth(id): Auth,
    Path((vault_id, group_id)): Path<(Uuid, Id)>,
) -> ApiResult<StatusCode> {
    access::vault(&state, &id, vault_id, VaultPermission::Edit).await?;
    let group = find_group(&state, vault_id, group_id).await?;
    let tx = state.db.begin().await?;
    DestroyGroup { account_id: id.user.account_id, vault_id, author_id: id.user.id, group_id: group.id }
        .execute(&tx)
        .await?;
    tx.commit().await?;
    Ok(StatusCode::NO_CONTENT)
}

